const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Look up all active promotions, especially those relevant to electronics
const promos = db.prepare(\"SELECT * FROM promotions WHERE active = 1\").all();
console.log('=== ALL ACTIVE PROMOTIONS ===');
promos.forEach(p => console.log(JSON.stringify(p, null, 2)));

// Also specifically check for ELEC15
console.log('\n=== ELEC15 LOOKUP (active or not) ===');
const elec15 = db.prepare(\"SELECT * FROM promotions WHERE promo_code = 'ELEC15'\").all();
if (elec15.length === 0) {
  console.log('No promotion found with code ELEC15');
} else {
  elec15.forEach(p => console.log(JSON.stringify(p, null, 2)));
}
"

node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

const user = db.prepare(\"SELECT * FROM users WHERE email = 'maya.chen@example.com'\").all();
console.log('=== USER LOOKUP ===');
user.forEach(u => {
  // Parse JSON fields for readability
  const parsed = {...u};
  ['preferences_json','purchase_history_json','payment_methods_json','saved_passengers_json','address_json','skill_ids_json'].forEach(k => {
    if (parsed[k]) try { parsed[k] = JSON.parse(parsed[k]); } catch(e) {}
  });
  console.log(JSON.stringify(parsed, null, 2));
});
if (user.length === 0) console.log('No user found with that email.');
"

